content:
.admin-shell { --admin-nav-height: calc(68px + env(safe-area-inset-bottom)); }

/* Admin navigation: quiet forest tones, consistent rhythm, readable contrast. */
#admin-sidebar {
  background: linear-gradient(165deg, #1b2923 0%, #121c18 42%, #111915 100%);
  border-right: 1px solid #ffffff0d;
  color: #f1f5f2;
  color-scheme: dark;
}
#admin-sidebar .admin-drawer-brand { padding: 24px 20px; gap: 12px; border-color: #ffffff0c; }
#admin-sidebar .admin-drawer-brand > img { width: 40px; height: 40px; border-radius: 12px; box-shadow: 0 0 0 1px #ffffff12; }
#admin-sidebar .admin-drawer-brand p:first-child { font-size: 14px; font-weight: 700; letter-spacing: .025em; }
#admin-sidebar .admin-drawer-brand p:last-child { color: #9aada1; font-size: 11px; }
#admin-sidebar .admin-drawer-brand > button { border: 1px solid #ffffff12; background: #ffffff04; color: #b4c2b9; border-radius: 50%; }
#admin-sidebar #admin-navigation-search { min-height: 46px; border-color: #ffffff14; background: #ffffff05; border-radius: 12px; font-size: 14px; color: #f1f5f2; }
#admin-sidebar #admin-navigation-search::placeholder { color: #8d9e94; }
#admin-sidebar #admin-navigation-search:focus { border-color: #8bb99b; box-shadow: 0 0 0 3px #8bb99b16; }
#admin-sidebar .admin-drawer-shortcuts { padding-top: 4px; padding-bottom: 14px; }
#admin-sidebar .admin-drawer-shortcuts > div { gap: 8px; }
#admin-sidebar .admin-drawer-shortcuts a { min-height: 64px; padding: 10px; border-color: #ffffff0e; background: #ffffff04; border-radius: 12px; }
#admin-sidebar .admin-drawer-shortcuts a:hover { background: #ffffff09; }
#admin-sidebar .admin-drawer-shortcuts a > div:first-child { width: 28px; height: 28px; border-radius: 9px; background: #a3b9ac12; }
#admin-sidebar .admin-drawer-shortcuts svg { stroke: #b1cbb9; }
#admin-sidebar .admin-drawer-shortcuts p:first-child { color: #95a79b; font-size: 10px; }
#admin-sidebar .admin-drawer-shortcuts p:last-child { font-size: 12px; font-weight: 600; }
#admin-sidebar .admin-drawer-navigation { padding: 0 12px 16px; scrollbar-width: thin; scrollbar-color: #52675a transparent; }
#admin-sidebar .admin-drawer-navigation::-webkit-scrollbar { width: 4px; }
#admin-sidebar .admin-drawer-navigation::-webkit-scrollbar-track { background: transparent; }
#admin-sidebar .admin-drawer-navigation::-webkit-scrollbar-thumb { background: #52675a; border-radius: 8px; }
#admin-sidebar .admin-drawer-section-heading { gap: 10px; padding: 24px 12px 10px; }
#admin-sidebar .admin-drawer-section-heading > span:first-child { display: none; }
#admin-sidebar .admin-drawer-section-heading p { color: #8d9f93; font-size: 9px; font-weight: 600; letter-spacing: .14em; }
#admin-sidebar .admin-drawer-section-heading > span:last-child { background: #ffffff0a; }
#admin-sidebar .admin-drawer-navigation a { min-height: 50px; padding: 8px 10px; gap: 12px; border-radius: 12px; color: #bdc9c1; font-size: 13px; font-weight: 500; }
#admin-sidebar .admin-drawer-navigation a:hover { background: #ffffff07; border-color: #ffffff0b; color: #fff; }
#admin-sidebar .admin-drawer-navigation a > span:first-child { width: 32px; height: 32px; background: transparent; color: #8fa89a; box-shadow: none; border-radius: 9px; }
#admin-sidebar .admin-drawer-navigation a[aria-current="page"] { background: #b4d3bf10; border-color: #b4d3bf26; color: #f1f8f3; box-shadow: inset 3px 0 0 #9cc5aa; font-weight: 600; }
#admin-sidebar .admin-drawer-navigation a[aria-current="page"] > span:first-child { background: #a8d1b51a; color: #bbdfc6; box-shadow: none; }
#admin-sidebar .admin-drawer-navigation a[aria-current="page"] > svg { color: #9fc4ac; }
#admin-sidebar .admin-drawer-navigation a > span:nth-child(3) { background: #d6b77719; border: 1px solid #d6b77724; color: #e6c990; min-width: 24px; padding: 3px 6px; font-size: 10px; font-weight: 600; box-shadow: none; }
#admin-sidebar .admin-drawer-footer { padding-top: 10px; border-color: #ffffff0c; background: #0c130f45; }
#admin-sidebar .admin-drawer-footer > a, #admin-sidebar .admin-drawer-footer > button { min-height: 44px; font-weight: 500; color: #a6b6ac; }
#admin-sidebar .admin-drawer-footer > a > span:first-child, #admin-sidebar .admin-drawer-footer > button > span:first-child { background: transparent; color: #8fa89a; }
#admin-sidebar .admin-drawer-footer > button:hover { color: #f0b3ad; }
#admin-sidebar :where(a, button, input):focus-visible { outline: 2px solid #b1d5be; outline-offset: 2px; }
@media (max-width: 1023px) {
  #admin-sidebar { width: min(90vw, 340px); box-shadow: 16px 0 64px #07100b40; }
}
/* Keep quantities readable in compact stock and variant controls. */
.admin-shell input[type="number"] { appearance: textfield; -moz-appearance: textfield; font-variant-numeric: tabular-nums; }
.admin-shell input[type="number"]::-webkit-inner-spin-button,
.admin-shell input[type="number"]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
.admin-shell :where(button, a, input, select, textarea, summary):focus-visible { outline: 2px solid #168526; outline-offset: 3px; }
.admin-shell #admin-main { scroll-padding-block: 5rem 10rem; }
.admin-cell-label { display: none; }
.admin-cell-value { min-width: 0; }
.admin-action-menu > summary { min-height: 44px; min-width: 44px; display: flex; align-items: center; justify-content: center; list-style: none; cursor: pointer; border-radius: 12px; border: 1px solid #ddd; background: white; }
.admin-action-menu > summary::-webkit-details-marker { display: none; }
.admin-action-menu[open] { flex-basis: 100%; }
.admin-action-menu[open] > summary { width: 44px; margin-left: auto; }
.admin-pagination { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-top: 16px; }
.admin-pagination button, .admin-filter-trigger { min-height: 44px; border: 1px solid #dedede; border-radius: 12px; padding: 8px 12px; background: white; font-size: 13px; font-weight: 600; }
.admin-pagination button:disabled { opacity: .4; }
.admin-pagination span { text-align: center; font-size: 13px; font-variant-numeric: tabular-nums; }
.admin-pagination small { display: block; font-size: 10px; color: #666; }
.admin-filter-trigger { display: flex; align-items: center; justify-content: center; gap: 8px; width: 100%; }
.admin-filter-dialog { padding: 0; border: 1px solid #ddd; border-radius: 22px 22px 0 0; width: 100%; max-width: 640px; max-height: 90dvh; margin: auto auto 0; background: white; color: #171717; }
.admin-filter-dialog::backdrop { background: #0008; }
.admin-filter-inner { display: flex; flex-direction: column; max-height: 90dvh; }
.admin-filter-dialog header, .admin-filter-dialog footer { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 16px; flex-shrink: 0; background: white; }
.admin-filter-dialog header { border-bottom: 1px solid #eee; font-weight: 700; }
.admin-filter-dialog button { min-height: 44px; min-width: 44px; border-radius: 12px; padding: 8px 12px; }
.admin-filter-dialog footer { padding-bottom: max(12px, env(safe-area-inset-bottom)); border-top: 1px solid #eee; }
.admin-filter-dialog .admin-filter-fields { padding: 16px; overflow-y: auto; min-height: 0; overscroll-behavior: contain; }
.admin-filter-fields { display: flex; flex-direction: column; gap: 12px; }
.admin-filter-dialog .admin-filter-fields > div { flex-wrap: wrap; }
.admin-filter-dialog input, .admin-filter-dialog select { min-height: 44px; max-width: 100%; min-width: 0; font-size: 16px; }
.admin-primary { color: white; background: #171717; font-weight: 700; }
.admin-mobile-section > summary { display: none; }
.admin-mobile-section > .admin-section-body { display: block; }
@media (min-width: 1024px) {
  .admin-mobile-section::details-content { content-visibility: visible; }
  .admin-filter-trigger { display: none; }
}
@media (max-width: 1023px) {
  .admin-shell #admin-main { padding-inline: max(12px, env(safe-area-inset-left)) max(12px, env(safe-area-inset-right)); }
  .admin-shell :where(input:not([type=checkbox]):not([type=radio]):not([type=hidden]):not([type=file]):not([type=color]), select, textarea) { font-size: 16px; min-height: 44px; max-width: 100%; min-width: 0; scroll-margin-block: 6rem; }
  .admin-shell :where(button, summary) { min-height: 44px; min-width: 44px; touch-action: manipulation; }
  .admin-shell :where(label:has(input[type=checkbox]), label:has(input[type=radio])) { min-height: 44px; }
  .admin-shell input:is([type=checkbox], [type=radio]) { width: 20px; height: 20px; flex-shrink: 0; accent-color: #168526; }
  .admin-shell :where(a[href^="tel:"], a[href^="https://wa.me"], a[href^="mailto:"]) { display: inline-flex; align-items: center; min-height: 44px; overflow-wrap: anywhere; }
  .admin-responsive-table { display: block !important; min-width: 0 !important; width: 100%; }
  .admin-responsive-table > thead { position: absolute !important; width: 1px; height: 1px; padding: 0; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  .admin-responsive-table > tbody { display: grid; gap: 12px; padding: 10px; }
  .admin-responsive-table > tbody > tr { display: block; border: 1px solid #e5e5e5; border-radius: 16px; padding: 12px; background: white; min-width: 0; }
  .admin-responsive-table > tbody > tr > td { display: grid !important; grid-template-columns: minmax(0, .7fr) minmax(0, 1.3fr); align-items: start; gap: 10px; padding: 8px 0; border: 0; text-align: left; min-width: 0; white-space: normal; }
  .admin-responsive-table .admin-cell-label { display: block; font-size: 11px; font-weight: 600; line-height: 1.6; color: #666; }
  .admin-responsive-table .admin-cell-value { overflow-wrap: anywhere; max-width: 100%; }
  .admin-responsive-table .admin-cell-value > .flex { flex-wrap: wrap; }
  .admin-responsive-table td[data-wide] { grid-template-columns: minmax(0, 1fr); }
  .admin-mobile-section { border: 1px solid #e5e5e5; border-radius: 18px; background: white; }
  .admin-mobile-section > summary { display: flex; align-items: center; justify-content: space-between; padding: 16px; font-size: 14px; font-weight: 700; list-style: none; cursor: pointer; }
  .admin-mobile-section > summary::-webkit-details-marker { display: none; }
  .admin-mobile-section[open] > summary .admin-section-chevron { transform: rotate(180deg); }
  .admin-mobile-section:not([open]) > .admin-section-body { display: none; }
  .admin-mobile-section > .admin-section-body > div { border: 0; box-shadow: none; }
  .admin-dialog-overlay { padding: max(12px, env(safe-area-inset-top)) 12px max(12px, env(safe-area-inset-bottom)) !important; }
  .admin-dialog-overlay > div { max-width: 100%; min-width: 0; max-height: calc(100dvh - 32px); overflow-y: auto; overscroll-behavior: contain; }
  .admin-form-actions { position: sticky; bottom: -1px; z-index: 10; background: white; border-top: 1px solid #eee; padding: 12px 0; }
  .admin-order-contact { position: sticky; bottom: 0; display: flex; gap: 8px; padding: 12px; padding-bottom: max(12px, env(safe-area-inset-bottom)); background: white; border-top: 1px solid #ddd; z-index: 25; }
  .admin-order-contact > * { display: flex; align-items: center; justify-content: center; min-height: 44px; flex: 1; border-radius: 12px; border: 1px solid #ddd; font-size: 12px; font-weight: 700; }
}

/* Mobile admin: one scrolling surface, with space reserved for each bottom bar. */
@media (max-width: 1023px) {
  .admin-shell { background: #f5f7f6; }
  .admin-shell #admin-main {
    padding: 20px max(16px, env(safe-area-inset-right)) calc(var(--admin-nav-height) + 24px) max(16px, env(safe-area-inset-left));
    scroll-padding-top: 20px;
    scrollbar-width: thin;
    scrollbar-color: #ccd9d0 transparent;
  }
  .admin-shell #admin-main::-webkit-scrollbar { width: 3px; }
  /* Match the mobile scroll container's 20px top padding. */
  .admin-shell #course-page-header { top: -20px; }
  /* The general input rule must not shrink the learning code editor. */
  .admin-shell #code-game-editor { min-height: 320px; }
  .admin-shell #admin-main::-webkit-scrollbar-thumb { background: #ccd9d0; border-radius: 4px; }
  .admin-topbar { border-color: #e9eeeb; box-shadow: none; }
  .admin-bottom-nav { background: #fff; border-color: #e5ebe7; box-shadow: 0 -2px 16px #173c2c05; }
  .admin-bottom-nav > div { max-width: 600px; margin-inline: auto; }
  .admin-bottom-nav a[aria-current="page"] { color: #173c2c; }
  .admin-bottom-nav a[aria-current="page"] > span:last-child { background-color: #218653; }
  .admin-product-editor { padding-bottom: 88px; }
  .admin-shell:has(.admin-product-editor) .admin-scroll-top { display: none; }
  .admin-editor-heading {
    position: static;
    margin: 0 0 20px;
    padding: 0 0 20px;
    background: transparent;
    border-color: #e0e7e2;
    backdrop-filter: none;
  }
  .admin-editor-heading h1 { font-size: 22px; line-height: 1.25; font-weight: 700; letter-spacing: -.04em; }
  .admin-editor-heading h1 + span { display: none; }
  .admin-editor-heading p { white-space: normal; color: #738079; font-size: 12px; line-height: 1.6; }
  .admin-editor-heading > div:first-child { align-items: flex-start; }
  .admin-editor-heading > div:first-child > button { border-radius: 14px; box-shadow: none; }
  .admin-editor-actions {
    bottom: var(--admin-nav-height);
    padding: 12px max(16px, env(safe-area-inset-right)) 12px max(16px, env(safe-area-inset-left));
    background: #fff;
    border-color: #e5ebe7;
    box-shadow: 0 -4px 16px #173c2c06;
    backdrop-filter: none;
  }
  .admin-editor-actions > div { max-width: 600px; gap: 10px; }
  .admin-editor-actions button { line-height: 1.3; }
  .admin-mobile-section { border-color: #e2e9e4; border-radius: 18px; box-shadow: 0 2px 5px #173c2c03; scroll-margin-top: 20px; }
  .admin-mobile-section > summary { gap: 16px; min-height: 62px; padding: 18px; font-size: 14px; font-weight: 600; color: #233d2e; }
  .admin-section-chevron { flex-shrink: 0; color: #7d8c82; transition: transform .18s ease; }
  .admin-mobile-section[open] > summary { border-bottom: 1px solid #edf1ee; }
  .admin-product-editor .admin-section-body > div { border-radius: 0 0 18px 18px; padding: 18px; }
  .admin-product-editor input, .admin-product-editor textarea, .admin-product-editor select { border-radius: 12px; }
  .admin-editor-import { margin-bottom: 0; border-radius: 18px; box-shadow: none; }
  .admin-dashboard-heading { padding: 4px 0 0; gap: 16px; }
  .admin-dashboard-heading h1 { font-size: 28px; font-weight: 700; letter-spacing: -.045em; }
  .admin-dashboard-heading > button { align-self: flex-start; width: auto; min-height: 44px; font-size: 12px; border-radius: 12px; box-shadow: none; }
  .admin-quick-action { flex-direction: column; align-items: flex-start; gap: 12px; padding: 16px; border-radius: 18px; box-shadow: none; }
  .admin-quick-action > span { width: 100%; }
  .admin-quick-action > span:first-child { width: 40px; height: 40px; }
  .admin-quick-action > span > span:first-child { white-space: normal; overflow: visible; font-size: 13px; font-weight: 600; }
  .admin-quick-action > svg { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .admin-section-chevron { transition: none; }
}

/* Shared mobile controls, with explicit layout hooks on admin screens. */
@media (max-width: 1023px) {
  .admin-shell #admin-main > :is(.p-4, .p-6, .p-8) { padding-inline: 0; padding-top: 0; }
  .admin-shell #admin-main > :is(div, section, form) { min-width: 0; max-width: 100%; }
  .admin-shell #admin-main :where(h1, h2, h3, p, label, legend) { overflow-wrap: anywhere; }
  .admin-shell #admin-main :where(input, select, textarea) { min-width: 0; max-width: 100%; }
  .admin-shell #admin-main :where(input[type="file"]:not(.sr-only)) { width: 100%; font-size: 13px; }
  .admin-shell #admin-main :where(input[type="file"]:not(.sr-only))::file-selector-button { min-height: 44px; margin-right: 8px; }
  .admin-shell #admin-main :where(textarea) { line-height: 1.6; }
  .admin-shell .admin-cell-value { width: 100%; }
  .admin-shell .admin-cell-value :where(img, video) { max-width: 100%; }
  .admin-shell .admin-cell-value :where(input, select, textarea) { width: 100%; }
  .admin-shell .admin-mobile-actions { flex-wrap: wrap; gap: 8px; min-width: 0; max-width: 100%; }
  .admin-shell .admin-mobile-actions > :is(button, a) { min-height: 44px; white-space: normal; line-height: 1.4; }
  .admin-shell .admin-mobile-tabs { max-width: 100%; min-width: 0; overflow-x: auto; overscroll-behavior-x: contain; }
  .admin-shell .admin-mobile-tabs > button { flex-shrink: 0; }
  .admin-shell .admin-mobile-master-detail { flex-direction: column; align-items: stretch; }
  .admin-shell .admin-mobile-master-detail > div { width: 100%; min-width: 0; }
  .admin-shell .admin-dialog-overlay { top: var(--admin-visible-top, 0px); bottom: auto; height: var(--admin-visible-height, 100dvh); overscroll-behavior: contain; }
  .admin-shell .admin-dialog-overlay > div { max-height: calc(var(--admin-visible-height, 100dvh) - 32px); border-radius: 20px; }
  .admin-shell .admin-dialog-overlay :where(.p-6, .p-8) { padding: 18px; }
  .admin-shell .admin-dialog-overlay :where(input, select, textarea) { scroll-margin-block: 80px; }
  .admin-shell .admin-filter-dialog, .admin-shell .admin-filter-inner { max-height: calc(var(--admin-visible-height, 100dvh) - 24px); }
  .admin-shell :is(.admin-filter-dialog, .admin-confirm-dialog) { margin: 0; left: 50%; top: calc(var(--admin-visible-top, 0px) + var(--admin-visible-height, 100dvh) / 2); transform: translate(-50%, -50%); max-height: calc(var(--admin-visible-height, 100dvh) - 24px); }
  .admin-shell .admin-filter-dialog { top: calc(var(--admin-visible-top, 0px) + var(--admin-visible-height, 100dvh)); transform: translate(-50%, -100%); }
  .admin-shell .admin-filter-dialog footer { gap: 8px; flex-wrap: wrap; }
  .admin-shell .admin-filter-dialog footer > button { flex: 1; }
}
@media (max-width: 767px) {
  .admin-shell .admin-support-selected .admin-support-hero { display: none; }
  .admin-shell .admin-support-frame { height: max(420px, calc(var(--admin-visible-height, 100dvh) - 180px)); min-height: 0; }
  .admin-shell .admin-support-thread-heading { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: 8px; padding: 12px; }
  .admin-shell .admin-support-thread-heading > select { grid-column: 1 / -1; width: 100%; }
  .admin-shell .admin-support-composer { display: grid; grid-template-columns: 48px minmax(0, 1fr); gap: 8px; }
  .admin-shell .admin-support-composer > textarea { width: 100%; min-width: 0; }
  .admin-shell .admin-support-composer > button { grid-column: 1 / -1; width: 100%; }
  .admin-shell .admin-mobile-heading { flex-direction: column; align-items: stretch; gap: 16px; }
  .admin-shell .admin-mobile-heading > * { min-width: 0; max-width: 100%; }
  .admin-shell .admin-mobile-heading > :is(button, a) { width: 100%; justify-content: center; min-height: 48px; }
  .admin-shell .admin-mobile-heading h1 { font-size: 24px; line-height: 1.3; }
  .admin-shell .admin-mobile-toolbar { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; }
  .admin-shell .admin-mobile-toolbar > :is(input, select, textarea, label, button) { width: 100%; min-width: 0; max-width: 100%; }
  .admin-shell .admin-mobile-card-layout { flex-direction: column; align-items: stretch; gap: 16px; }
  .admin-shell .admin-mobile-card-layout > * { width: 100%; min-width: 0; }
  .admin-shell .admin-mobile-card-layout > :last-child { flex-wrap: wrap; justify-content: flex-start; }
  .admin-shell .admin-mobile-card-layout > :last-child > :is(button, a) { min-height: 44px; }
}
@media (max-width: 639px) {
  .admin-shell .admin-mobile-fields { grid-template-columns: minmax(0, 1fr); gap: 16px; }
  .admin-shell .admin-mobile-fields > * { min-width: 0; max-width: 100%; }
  .admin-shell .admin-mobile-fields > :is(.col-span-2, .col-span-3, .col-span-4) { grid-column: auto; }
  .admin-shell .admin-dialog-overlay .admin-mobile-actions > button { flex: 1 1 auto; }
}
@media (max-width: 479px) {
  .admin-shell .admin-responsive-table > tbody > tr > td { grid-template-columns: minmax(0, 1fr); gap: 4px; padding: 9px 0; }
  .admin-shell .admin-cell-label { font-size: 11px; line-height: 1.4; }
  .admin-shell .admin-cell-value { font-size: 13px; line-height: 1.6; }
  .admin-shell .admin-pagination { flex-wrap: wrap; }
  .admin-shell .admin-pagination button { font-size: 12px; padding-inline: 10px; }
}
